class YTDLPLogger:
    def __init__(self, app, platform="Generic"):
        self.app = app
        self.platform = platform

    def _clean_prefix(self, msg):
        msg = str(msg)
        return re.sub(r'^\[[^\]]+\]\s*', '', msg).strip()

    def debug(self, msg):
        msg = str(msg)
        if any(x in msg for x in ["Destination:", "Resuming download", "Extracting URL", "Downloading"]):
            clean = self._clean_prefix(msg.replace("[debug] ", ""))
            self.app.log_message(f"🔎 {clean}", "INFO", self.platform)

    def info(self, msg):
        clean = self._clean_prefix(str(msg).replace("[info] ", ""))
        self.app.log_message(f"💬 {clean}", "INFO", self.platform)

    def warning(self, msg):
        msg = str(msg)
        if "JavaScript runtime" in msg or "deprecated" in msg: return
        clean = self._clean_prefix(msg.replace("[warning] ", ""))
        self.app.log_message(f"⚠️ {clean}", "WARN", self.platform)

    def error(self, msg):
        clean = self._clean_prefix(str(msg).replace("[error] ", ""))
        self.app.log_message(f"❌ {clean}", "ERRO", self.platform)

class MusicDownloaderApp(ctk.CTk):
    def __init__(self):
        super().__init__()

        self.title("DivisionX - Downloader multi-plataforma")
        self.geometry("860x980")
        self.minsize(720, 840)
        self.configure(fg_color=PURPLE_DARK)
        self.resizable(True, True)

        try:
            icon_image = tk.PhotoImage(data=LOGO_BASE64)
            self.iconphoto(False, icon_image)
        except Exception:
            pass

        self.base_font_size = 20

        self.config_data = self._load_config()
        self.download_folder = self.config_data.get("last_folder", os.path.expanduser("~/Music"))

        self.day_numbers = {
            0: "001", 1: "002", 2: "003", 3: "004", 4: "005", 5: "006", 6: "007"
        }

        self.day_options = [
            "Segunda-Feira", "Terça-Feira", "Quarta-Feira", "Quinta-Feira",
            "Sexta-Feira", "Sábado", "Domingo", "Personalizado"
        ]

        self.thumbnail_image = None
        self._build_ui()
        self.log_message("🟢 Interface inicializada e pronta.", "INFO", "Sistema")

    def _load_config(self):
        if os.path.exists(CONFIG_FILE):
            try:
                with open(CONFIG_FILE, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception: pass
        return {}

    def _save_config(self):
        self.config_data["last_folder"] = self.path_entry.get().strip()
        self.config_data["font_size"] = self.base_font_size
        self.config_data["tok_escola_mode"] = self.tok_escola_var.get()
        try:
            with open(CONFIG_FILE, "w", encoding="utf-8") as f:
                json.dump(self.config_data, f, indent=4)
        except Exception as e:
            self.log_message(f"⚠️ Falha ao salvar preferências: {str(e)}", "WARN", "Sistema")

    def _get_font(self, size_offset=0, weight="normal"):
        return ctk.CTkFont(family=FONT_FAMILY, size=self.base_font_size + size_offset, weight=weight)

    def _clean_url_string(self, raw_url: str) -> str:
        raw_url = raw_url.strip()
        if not raw_url: return ""
        parsed = urlparse(raw_url)
        netloc = parsed.netloc.lower()
        path = parsed.path

        if "youtube.com" in netloc:
            if path == "/watch":
                query_params = parse_qs(parsed.query)
                video_id = query_params.get('v')
                if video_id:
                    new_query = urlencode({'v': video_id[0]})
                    return urlunparse((parsed.scheme or "https", parsed.netloc, path, '', new_query, ''))
            elif path.startswith("/shorts/"):
                return urlunparse((parsed.scheme or "https", parsed.netloc, path.split("?")[0], '', '', ''))
        elif "youtu.be" in netloc:
            return urlunparse((parsed.scheme or "https", parsed.netloc, path.split("?")[0], '', '', ''))

        return urlunparse((parsed.scheme or "https", parsed.netloc, path, '', '', ''))

    def _force_format_time(self, widget):
        val = widget.get().replace(":", "").strip()
        if not val or not val.isdigit(): return
        
        if len(val) <= 2:
            formatted = f"00:{int(val):02d}"
        elif len(val) <= 4:
            formatted = f"{int(val[:-2]):02d}:{int(val[-2:]):02d}"
        else:
            formatted = f"{int(val[:-4]):02d}:{int(val[-4:-2]):02d}:{int(val[-2:]):02d}"
        
        widget.delete(0, 'end')
        widget.insert(0, formatted)

    def _on_time_focus_out(self, event):
        self._force_format_time(event.widget)

